method intDivImpl(n:int, d:int) returns (q:int, r:int)
requires n >= 0 && d > 0;
ensures (d*q)+r == n && 0 <= q <= n/2 && 0 <= r < d; 
{
    q := 0;
    r := n;
    while r >= d
        invariant r == n - q * d;
        invariant d <= r;
        r := r-1;
    {
        r := r - d;
        q := q + 1;
    } 
    assert n == (d * q) + r;
